#include <algorithm>
#include <fstream>
#include <vector>
int main() {
    std::ifstream in("angry.in");
    std::ofstream out("angry.out");
    int n, k;
    in >> n >> k;
    std::vector<long long> x(n);
    for (auto& p : x) in >> p;
    std::sort(x.begin(), x.end());
    auto possible = [&](long long radius) {
        int used = 0, i = 0;
        while (i < n) {
            if (++used > k) return false;
            long long right = x[i] + 2 * radius;
            while (i < n && x[i] <= right) ++i;
        }
        return true;
    };
    long long low = 0, high = 1000000000LL;
    while (low < high) {
        long long mid = low + (high - low) / 2;
        if (possible(mid)) high = mid;
        else low = mid + 1;
    }
    out << low << '\n';
}
