#include <algorithm>
#include <array>
#include <fstream>
int main() {
    std::ifstream in("div7.in");
    std::ofstream out("div7.out");
    int n;
    in >> n;
    std::array<int, 7> first;
    first.fill(-1);
    first[0] = 0;
    int remainder = 0, answer = 0;
    for (int i = 1; i <= n; ++i) {
        int id;
        in >> id;
        remainder = (remainder + id) % 7;
        if (first[remainder] == -1) first[remainder] = i;
        else answer = std::max(answer, i - first[remainder]);
    }
    out << answer << '\n';
}
