#include <array>
#include <fstream>
#include <set>
#include <string>
#include <utility>
int main() {
    std::ifstream in("gates.in");
    std::ofstream out("gates.out");
    int n;
    std::string path;
    in >> n >> path;
    std::set<std::pair<int, int>> vertices;
    std::set<std::array<int, 4>> edges;
    int x = 0, y = 0;
    vertices.insert({x, y});
    for (char direction : path) {
        int nx = x, ny = y;
        if (direction == 'N') ++ny;
        else if (direction == 'S') --ny;
        else if (direction == 'E') ++nx;
        else --nx;
        std::pair<int, int> a{x, y}, b{nx, ny};
        if (b < a) std::swap(a, b);
        edges.insert({a.first, a.second, b.first, b.second});
        vertices.insert({nx, ny});
        x = nx;
        y = ny;
    }
    out << static_cast<int>(edges.size()) - static_cast<int>(vertices.size()) + 1 << '\n';
}
